package com.eventdrivencommerce.payment.domain;
import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;import static org.assertj.core.api.Assertions.*;
class PaymentTest{private static final Instant NOW=Instant.parse("2026-08-11T20:00:00Z");@Test void completesAndRefunds(){var p=Payment.pending(UUID.randomUUID(),new BigDecimal("199.80"),"sek",NOW);p.complete("sim_cap_12345678",NOW.plusSeconds(1));var refund=p.requestRefund(NOW.plusSeconds(2));p.refundComplete("sim_ref_12345678",NOW.plusSeconds(3));assertThat(refund).isNotNull();assertThat(p.status()).isEqualTo(PaymentStatus.REFUNDED);}@Test void recordsDeterministicFailure(){var p=Payment.pending(UUID.randomUUID(),new BigDecimal("10.00"),"SEK",NOW);p.fail("SIMULATED_DECLINE",NOW);assertThat(p.status()).isEqualTo(PaymentStatus.FAILED);assertThat(p.failureReason()).isEqualTo("SIMULATED_DECLINE");}@Test void rejectsInvalidTransition(){var p=Payment.pending(UUID.randomUUID(),new BigDecimal("10.00"),"SEK",NOW);assertThatThrownBy(()->p.requestRefund(NOW)).isInstanceOf(IllegalStateException.class);}}
